script:
carrier_event = {
	id = paragon.99
	hide_window = yes
	location = from
	is_triggered_only = yes

	trigger = {
		has_paragon_dlc = yes
	}

	immediate = {
		if = {
			limit = { free_building_slots >= 1 }
			# A bit of flare
			spawn_planet_temperature_effect = yes
			# Add building if applicable
			if = {
				limit = { NOT = { has_building = building_the_beholder } }
				set_timed_carrier_flag = {
					flag = ignore_ai_building_limitations
					days = 1
				}
				add_building = building_the_beholder
			}
			# Unassign Beholder from ship before class change so change_leader_class takes effect.
			event_target:beholder_ship = {
				leader = { unassign_leader = this }
				delete_ship = this
			}
			# Change Beholder into an official.
			event_target:beholder_leader = {
				remove_trait = leader_trait_scout
				remove_trait = leader_trait_energy_weapon_specialist
				remove_trait = leader_trait_cautious
				remove_trait = leader_trait_psionic
				remove_trait = subclass_commander_admiral
				change_leader_class = official
				add_trait = {
					trait = subclass_official_governor
					show_message = no
					consume_selection = yes
				}
				add_trait = {
					trait = leader_trait_governor_psionic_communion
					show_message = no
					consume_selection = yes
				}
				add_trait = {
					trait = leader_trait_mediator
					show_message = no
					consume_selection = yes
				}
				add_trait = {
					trait = leader_trait_industrial_focus_2
					show_message = no
					consume_selection = yes
				}
				add_trait = {
					trait = leader_trait_intellectual
					show_message = no
					consume_selection = yes
				}
			}
			# Unassign current governor, then assign Beholder as governor.
			colony = {
				if = {
					limit = { exists = leader }
					leader = { unassign_leader = this }
				}
				assign_leader = event_target:beholder_leader
			}
			# Notification
			create_message = {
				type = MESSAGE_BEHOLDER_PLANETFALL
				localization = MESSAGE_BEHOLDER_PLANETFALL_DESC
				days = 10
				target = THIS
				variable = {
					type = name
					localization = PLANET
					scope = this
				}
			}
		}
		else = {
			# Notification
			create_message = {
				type = MESSAGE_BEHOLDER_PLANETFALL_NO_SLOTS
				localization = MESSAGE_BEHOLDER_PLANETFALL_NO_SLOTS_DESC
				days = 10
				target = THIS
				variable = {
					type = name
					localization = PLANET
					scope = this
				}
			}
		}
	}
}

