		carrier_event = { id = paragon.252 days = 3 }

		remove_carrier_flag = terraform_nucleus_transfix_canceled
		set_carrier_flag = terraform_nucleus_transfix_started

		# Set vars to adapt effect to planet size
		export_trigger_value_to_variable = {
			trigger = planet_size
			variable = effect_size_var
		}
		multiply_variable = {
			which = effect_size_var
			value = 0.13
		}
		create_ambient_object = {
			type = terraforming_planet_effect
			location = this
			use_3d_location = yes
			entity_scale_to_size = yes
			scripted_scale = effect_size_var
		}
		last_created_ambient_object = {
			set_ambient_object_flag = azaryn_terraforming_effect
		}
		# Set vars to adapt beam to planet size
		export_trigger_value_to_variable = {
			trigger = planet_size
			variable = beam_size_var
		}
		switch = {
			trigger = planet_size
